package com.zxl.zxlaiagent.knowledge.memory;

import com.zxl.zxlaiagent.knowledge.KnowledgeDatabase;
import com.fasterxml.jackson.annotation.JsonFormat;
import com.zxl.zxlaiagent.security.Phase;
import com.zxl.zxlaiagent.security.execution.OperationBoundary;
import java.sql.*;
import java.time.*;
import java.util.*;

/** Explicit user preference proposals. A demo scope is not login or permission delegation. */
public final class MemoryService {
 @FunctionalInterface public interface SourceVerifier {OperationBoundary verify(String session,String message,String text);}
 public record Scope(String tenantId,String userId){public Scope{if(tenantId==null||userId==null||tenantId.isBlank()||userId.isBlank()||tenantId.length()>150||userId.length()>150||tenantId.chars().anyMatch(Character::isISOControl)||userId.chars().anyMatch(Character::isISOControl))throw new IllegalArgumentException("Invalid trusted scope");}}
 public record Memory(String id,String factKey,String value,String sourceText,String sessionId,String messageId,String state,long version,@JsonFormat(shape=JsonFormat.Shape.STRING) Instant createdAt,@JsonFormat(shape=JsonFormat.Shape.STRING) Instant expiresAt,@JsonFormat(shape=JsonFormat.Shape.STRING) Instant deletedAt){}
 public record Fact(String id,String factKey,String value,long version,@JsonFormat(shape=JsonFormat.Shape.STRING) Instant expiresAt){}
 public record Recall(List<Fact> facts,int usedChars,int droppedCount){}
 public static final class Conflict extends RuntimeException {public Conflict(){super("记忆版本已变化、已失效或已处理，请刷新后重试");}}
 private final OperationBoundary boundary;private final SourceVerifier sourceVerifier;
 private final KnowledgeDatabase db;private final Scope scope;private final Clock clock;
 public MemoryService(KnowledgeDatabase db,Scope scope,Clock clock){this(db,scope,clock,OperationBoundary.unrestricted(),(session,message,text)->OperationBoundary.unrestricted());}
 public MemoryService(KnowledgeDatabase db,Scope scope,Clock clock,OperationBoundary boundary,SourceVerifier sourceVerifier){this.boundary=java.util.Objects.requireNonNull(boundary);this.sourceVerifier=java.util.Objects.requireNonNull(sourceVerifier);this.db=db;this.scope=scope;this.clock=clock;}
 public Scope scope(){return scope;}
 public static Scope demoScope(String profile){return switch(profile==null?"alice":profile){case "alice"->new Scope("demo-enterprise","demo-user-a");case "bob"->new Scope("demo-enterprise","demo-user-b");default->throw new IllegalArgumentException("Only registered demo profiles alice/bob are allowed");};}
 private record Extracted(String key,String value){}
 private static Extracted extract(String text){if(text==null)throw new IllegalArgumentException("Explicit user text required");return switch(text){case "我偏好中文回复","I prefer Chinese replies"->new Extracted("reply_language","zh");case "我偏好英文回复","I prefer English replies"->new Extracted("reply_language","en");case "我偏好简洁回复","I prefer concise replies"->new Extracted("reply_detail","concise");case "我偏好详细回复","I prefer detailed replies"->new Extracted("reply_detail","detailed");case "我偏好列表回复","I prefer bullet lists"->new Extracted("reply_format","bullets");case "我偏好段落回复","I prefer paragraphs"->new Extracted("reply_format","paragraphs");default->throw new IllegalArgumentException("只接受明确原话：我偏好中文/英文/简洁/详细/列表/段落回复；不提取敏感信息或权限");};}
 private static void source(String session,String message,int ttl){if(session==null||message==null||!session.matches("[A-Za-z0-9_-]{1,80}")||!message.matches("[A-Za-z0-9_-]{1,80}")||ttl<5||ttl>2592000)throw new IllegalArgumentException("来源ID须1..80位安全字符；演示TTL须5秒..30天");}
 public Memory propose(String session,String message,String text,int ttl){source(session,message,ttl);OperationBoundary sourceBoundary=sourceVerifier.verify(session,message,text);var e=extract(text);Instant now=clock.instant();return sourceBoundary.start(Phase.RESULT_PERSIST,()->db.tx(c->{lock(c);Memory replay=byMessage(c,message);if(replay!=null){if(!replay.sourceText().equals(text)||!replay.sessionId().equals(session))throw new Conflict();return replay;}retireExpired(c,e.key(),now);try(var s=KnowledgeDatabase.statement(c,"SELECT memory_id FROM confirmed_memory WHERE tenant_id=? AND user_id=? AND fact_key=? AND state IN ('PENDING','CONFIRMED')",scope.tenantId(),scope.userId(),e.key());var r=s.executeQuery()){if(r.next())throw new Conflict();}String id=UUID.randomUUID().toString();try(var s=KnowledgeDatabase.statement(c,"INSERT INTO confirmed_memory(memory_id,tenant_id,user_id,fact_key,fact_value,source_text,session_id,message_id,extraction_version,state,version,created_at,updated_at,expires_at) VALUES(?,?,?,?,?,?,?,?,?,'PENDING',1,?,?,?)",id,scope.tenantId(),scope.userId(),e.key(),e.value(),text,session,message,"explicit-whitelist-v1",Timestamp.from(now),Timestamp.from(now),Timestamp.from(now.plusSeconds(ttl)))){s.executeUpdate();}return get(c,id);}));}
 private void lock(Connection c)throws SQLException{try(var s=KnowledgeDatabase.statement(c,"SELECT pg_advisory_xact_lock(hashtextextended(?,0))",scope.tenantId()+":"+scope.userId())){s.execute();}}
 private void retireExpired(Connection c,String key,Instant now)throws SQLException{try(var s=KnowledgeDatabase.statement(c,"UPDATE confirmed_memory SET state='DELETED',deleted_at=?,updated_at=?,version=version+1 WHERE tenant_id=? AND user_id=? AND fact_key=? AND state IN ('PENDING','CONFIRMED') AND expires_at<=?",Timestamp.from(now),Timestamp.from(now),scope.tenantId(),scope.userId(),key,Timestamp.from(now))){s.executeUpdate();}}
 public List<Memory> list(){return boundary.start(Phase.RESULT_PERSIST,()->db.tx(c->{var out=new ArrayList<Memory>();try(var s=KnowledgeDatabase.statement(c,"SELECT * FROM confirmed_memory WHERE tenant_id=? AND user_id=? AND deleted_at IS NULL ORDER BY created_at DESC,memory_id",scope.tenantId(),scope.userId());var r=s.executeQuery()){while(r.next())out.add(row(r));}return List.copyOf(out);}));}
 public Memory confirm(String id,long version){return transition(id,version,"CONFIRMED");}
 public Memory reject(String id,long version){return transition(id,version,"REJECTED");}
 public Memory delete(String id,long version){return transition(id,version,"DELETED");}
 private Memory transition(String id,long version,String target){if(version<1)throw new IllegalArgumentException("version required");return boundary.start(Phase.RESULT_PERSIST,()->db.tx(c->{lock(c);var current=get(c,id);Instant now=clock.instant();if(current.state().equals(target)&&(current.version()==version||current.version()==version+1)&&(target.equals("DELETED")||current.expiresAt().isAfter(now)))return current;if(current.version()!=version||current.deletedAt()!=null||(!target.equals("DELETED")&&!current.expiresAt().isAfter(now)))throw new Conflict();if(!target.equals("DELETED")&&!current.state().equals("PENDING"))throw new Conflict();try(var s=KnowledgeDatabase.statement(c,"UPDATE confirmed_memory SET state=?,version=version+1,updated_at=?,deleted_at=? WHERE memory_id=? AND tenant_id=? AND user_id=? AND version=?",target,Timestamp.from(now),target.equals("DELETED")?Timestamp.from(now):null,id,scope.tenantId(),scope.userId(),version)){if(s.executeUpdate()!=1)throw new Conflict();}return get(c,id);}));}
 public Memory correct(String id,long version,String session,String message,String text,int ttl){source(session,message,ttl);OperationBoundary sourceBoundary=sourceVerifier.verify(session,message,text);var e=extract(text);return sourceBoundary.start(Phase.RESULT_PERSIST,()->db.tx(c->{lock(c);var current=get(c,id);if(byMessage(c,message)!=null)throw new Conflict();Instant now=clock.instant();if(current.version()!=version||!current.state().equals("CONFIRMED")||!current.expiresAt().isAfter(now)||!e.key().equals(current.factKey()))throw new Conflict();try(var s=KnowledgeDatabase.statement(c,"UPDATE confirmed_memory SET fact_value=?,source_text=?,session_id=?,message_id=?,state='PENDING',version=version+1,updated_at=?,expires_at=? WHERE memory_id=? AND tenant_id=? AND user_id=? AND version=?",e.value(),text,session,message,Timestamp.from(now),Timestamp.from(now.plusSeconds(ttl)),id,scope.tenantId(),scope.userId(),version)){if(s.executeUpdate()!=1)throw new Conflict();}return get(c,id);}));}
 public Recall recall(int maxChars,Duration budget){if(maxChars<5||maxChars>2000)throw new IllegalArgumentException("memory budget 5..2000 chars");if(budget==null||budget.isZero()||budget.isNegative())throw new IllegalArgumentException("positive remaining budget required");return boundary.start(Phase.EVIDENCE_READ,()->db.tx(budget,c->{var facts=new ArrayList<Fact>();int used=0,dropped=0;try(var s=KnowledgeDatabase.statement(c,"SELECT * FROM confirmed_memory WHERE tenant_id=? AND user_id=? AND state='CONFIRMED' AND deleted_at IS NULL AND expires_at>? ORDER BY updated_at DESC,memory_id",scope.tenantId(),scope.userId(),Timestamp.from(clock.instant()));var r=s.executeQuery()){while(r.next()){var m=row(r);int chars=m.factKey().length()+m.value().length()+2;if(facts.size()>=5||used+chars>maxChars){dropped++;continue;}facts.add(new Fact(m.id(),m.factKey(),m.value(),m.version(),m.expiresAt()));used+=chars;}}return new Recall(List.copyOf(facts),used,dropped);}));}
 private Memory byMessage(Connection c,String message)throws SQLException{try(var s=KnowledgeDatabase.statement(c,"SELECT m.* FROM confirmed_memory m WHERE m.tenant_id=? AND m.user_id=? AND (m.message_id=? OR EXISTS (SELECT 1 FROM confirmed_memory_history h WHERE h.memory_id=m.memory_id AND h.previous_record->>'message_id'=?)) ORDER BY m.created_at,m.memory_id LIMIT 1",scope.tenantId(),scope.userId(),message,message);var r=s.executeQuery()){return r.next()?row(r):null;}}
 private Memory get(Connection c,String id)throws SQLException{try(var s=KnowledgeDatabase.statement(c,"SELECT * FROM confirmed_memory WHERE memory_id=? AND tenant_id=? AND user_id=? FOR UPDATE",id,scope.tenantId(),scope.userId());var r=s.executeQuery()){if(!r.next())throw new NoSuchElementException("Memory not found");return row(r);}}
 private static Memory row(ResultSet r)throws SQLException{Timestamp deleted=r.getTimestamp("deleted_at");return new Memory(r.getString("memory_id"),r.getString("fact_key"),r.getString("fact_value"),r.getString("source_text"),r.getString("session_id"),r.getString("message_id"),r.getString("state"),r.getLong("version"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("expires_at").toInstant(),deleted==null?null:deleted.toInstant());}
}
